`timescale 1ns / 1ps
// Repro A (period): rising edge to rising edge must be PERIOD cycles.
module tb_pwm_repro;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd0;
    wire pwm;
    integer passed = 0;
    integer failed = 0;
    integer cyc;
    integer i;
    reg ok;
    reg done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check;
        input cond;
        input [8*40-1:0] label;
        input integer got;
        input integer exp;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("CHECK PASS %0s got=%0d exp=%0d", label, got, exp);
            end else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s got=%0d exp=%0d", label, got, exp);
            end
        end
    endtask

    task do_reset;
        input [3:0] d;
        begin
            rst = 1'b1;
            duty = d;
            repeat (3) @(negedge clk);
            rst = 1'b0;
        end
    endtask

    // Waits for the next rising edge of pwm (sampled at negedges).
    // cyc = negedges waited, ok = edge seen within the bound.
    task wait_rise;
        integer n;
        reg last;
        begin
            ok = 1'b0;
            n = 0;
            last = pwm;
            while (!ok && n < 64) begin
                @(negedge clk);
                n = n + 1;
                if (pwm && !last) ok = 1'b1;
                last = pwm;
            end
            cyc = n;
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";

        do_reset(4'd3);
        wait_rise;
        check(ok, "PERIOD_FIRST_RISE_D3", ok, 1);
        wait_rise;
        for (i = 0; i < 3; i = i + 1) begin
            wait_rise;
            check(ok && (cyc == PERIOD), "PERIOD_RISE_TO_RISE_D3", cyc, PERIOD);
        end

        do_reset(4'd5);
        wait_rise;
        check(ok, "PERIOD_FIRST_RISE_D5", ok, 1);
        wait_rise;
        for (i = 0; i < 3; i = i + 1) begin
            wait_rise;
            check(ok && (cyc == PERIOD), "PERIOD_RISE_TO_RISE_D5", cyc, PERIOD);
        end

        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #200000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK FAIL WATCHDOG");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===

