`timescale 1ns / 1ps
// Repro B (pulse width): each high run must last exactly `duty` cycles;
// duty 0 must keep the output low.
module tb_pwm_repro;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd0;
    wire pwm;
    integer passed = 0;
    integer failed = 0;
    integer cyc;
    integer i;
    integer k;
    integer d;
    integer highs;
    reg ok;
    reg done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check;
        input cond;
        input [8*40-1:0] label;
        input integer got;
        input integer exp;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("CHECK PASS %0s got=%0d exp=%0d", label, got, exp);
            end else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s got=%0d exp=%0d", label, got, exp);
            end
        end
    endtask

    task do_reset;
        input [3:0] dv;
        begin
            rst = 1'b1;
            duty = dv;
            repeat (3) @(negedge clk);
            rst = 1'b0;
        end
    endtask

    task wait_rise;
        integer n;
        reg last;
        begin
            ok = 1'b0;
            n = 0;
            last = pwm;
            while (!ok && n < 64) begin
                @(negedge clk);
                n = n + 1;
                if (pwm && !last) ok = 1'b1;
                last = pwm;
            end
            cyc = n;
        end
    endtask

    // Called at the first high sample; ends at the first low sample.
    task measure_high;
        integer n;
        reg run;
        begin
            n = 1;
            run = 1'b1;
            while (run && n < 64) begin
                @(negedge clk);
                if (pwm) n = n + 1;
                else run = 1'b0;
            end
            cyc = n;
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";

        for (k = 0; k < 3; k = k + 1) begin
            d = 1 + 2 * k; // 1, 3, 5
            do_reset(d[3:0]);
            wait_rise;
            wait_rise;
            for (i = 0; i < 3; i = i + 1) begin
                if (!ok) begin
                    check(1'b0, "PULSE_RISE_SEEN", 0, 1);
                end else begin
                    measure_high;
                    check(cyc == d, "PULSE_HIGH_RUN", cyc, d);
                end
                wait_rise;
            end
        end

        do_reset(4'd0);
        highs = 0;
        for (i = 0; i < 4 * PERIOD; i = i + 1) begin
            @(negedge clk);
            if (pwm) highs = highs + 1;
        end
        check(highs == 0, "DUTY0_STAYS_LOW", highs, 0);

        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #200000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK FAIL WATCHDOG");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===

