`timescale 1ns / 1ps
// Repro C (duty update): duty is sampled at the start of a period; a change in
// the middle of a period must not alter that period, only the next one.
module tb_pwm_repro;
    localparam integer PERIOD = 8;
    reg clk = 1'b0;
    reg rst = 1'b1;
    reg [3:0] duty = 4'd0;
    wire pwm;
    integer passed = 0;
    integer failed = 0;
    integer cyc;
    integer high0, low0, low1, high1, high2, high3, high4;
    reg ok;
    reg done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(PERIOD)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task check;
        input cond;
        input [8*40-1:0] label;
        input integer got;
        input integer exp;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("CHECK PASS %0s got=%0d exp=%0d", label, got, exp);
            end else begin
                failed = failed + 1;
                $display("CHECK FAIL %0s got=%0d exp=%0d", label, got, exp);
            end
        end
    endtask

    task do_reset;
        input [3:0] dv;
        begin
            rst = 1'b1;
            duty = dv;
            repeat (3) @(negedge clk);
            rst = 1'b0;
        end
    endtask

    task wait_rise;
        integer n;
        reg last;
        begin
            ok = 1'b0;
            n = 0;
            last = pwm;
            while (!ok && n < 64) begin
                @(negedge clk);
                n = n + 1;
                if (pwm && !last) ok = 1'b1;
                last = pwm;
            end
            cyc = n;
        end
    endtask

    // Called at the first high sample; ends at the first low sample.
    task measure_high;
        integer n;
        reg run;
        begin
            n = 1;
            run = 1'b1;
            while (run && n < 64) begin
                @(negedge clk);
                if (pwm) n = n + 1;
                else run = 1'b0;
            end
            cyc = n;
        end
    endtask

    // Called at the first low sample; ends at the first high sample.
    task measure_low;
        integer n;
        reg run;
        begin
            n = 1;
            run = 1'b1;
            while (run && n < 64) begin
                @(negedge clk);
                if (!pwm) n = n + 1;
                else run = 1'b0;
            end
            cyc = n;
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";

        do_reset(4'd2);
        wait_rise;
        wait_rise;
        check(ok, "DUTY_STEADY_RISE_SEEN", ok, 1);

        // Steady period at duty 2.
        measure_high; high0 = cyc;
        measure_low;  low0 = cyc;          // now at a rise sample

        // Raise duty during the low part of a period.
        measure_high;                       // now at the first low sample
        duty = 4'd5;
        measure_low;  low1 = cyc;
        check(low1 == low0, "DUTY_RAISE_MIDPERIOD_LOW_KEPT", low1, low0);
        measure_high; high1 = cyc;
        check(high1 > high0, "DUTY_RAISE_TAKES_EFFECT_NEXT", high1, high0);

        // One steady period at duty 5.
        measure_low;                        // now at a rise sample
        measure_high; high2 = cyc;
        measure_low;                        // now at a rise sample

        // Lower duty during the high part of a period.
        duty = 4'd1;
        measure_high; high3 = cyc;
        check(high3 == high2, "DUTY_LOWER_MIDPERIOD_HIGH_KEPT", high3, high2);
        measure_low;
        measure_high; high4 = cyc;
        check(high4 < high2, "DUTY_LOWER_TAKES_EFFECT_NEXT", high4, high2);

        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #200000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK FAIL WATCHDOG");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===
